<?php
require_once __DIR__.'/includes/auth.php';
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$sid=trim($_POST['student_id']??'');$dept=trim($_POST['department']??'');$pass=$_POST['password']??'';
 if(strlen($pass)<8)$error='Password must contain at least 8 characters.';
 else {try{$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'student')");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$s=$pdo->prepare("INSERT INTO students(user_id,student_id,department) VALUES(?,?,?)");$s->execute([$uid,$sid,$dept]);$pdo->commit();flash('Registration successful. You can now sign in.');redirect('login.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not register. Check that the email and student ID are unique.';}}
}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Registration</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style.css" rel="stylesheet"></head><body><div class="auth-wrap"><div class="auth-card"><a class="brand" href="index.php">◈ LabDesk</a><h1>Student registration</h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php foreach(['name'=>'Full name','email'=>'Email','student_id'=>'Student ID','department'=>'Department'] as $k=>$label):?><label class="form-label"><?=$label?></label><input class="form-control mb-3" name="<?=$k?>" <?= $k==='email'?'type="email"':''?> required><?php endforeach?><label class="form-label">Password (minimum 8 characters)</label><input class="form-control mb-3" type="password" name="password" minlength="8" required><button class="btn btn-primary w-100">Register</button></form><p class="muted mt-3">Already registered? <a href="login.php">Login</a></p></div></div></body></html>
